<script setup lang="ts">const shop=useShop(); const email=ref(''); function submit(){if(!/^\S+@\S+\.\S+$/.test(email.value)){shop.notify('Enter a valid email address.','error');return}shop.notify('You are on the demo list. No email was sent.');email.value=''} </script>
<template><form class="flex w-full max-w-md gap-2" @submit.prevent="submit"><input v-model="email" type="email" required placeholder="Your email address" class="min-w-0 flex-1 rounded-full border border-gray-200 bg-white px-4 py-3 text-sm outline-none transition focus:border-brand"><button class="shrink-0 rounded-full bg-ink px-5 py-3 text-xs font-bold uppercase tracking-wider text-white transition hover:bg-brand">Sign me up ↗</button></form></template>
